(function(){'use strict';var state={results:null,history:[]};var elements={};

function init(){elements={input:document.getElementById('hg-input'),options:document.getElementById('hg-options'),resultsDiv:document.getElementById('hg-results'),generateBtn:document.getElementById('generate-btn'),resetBtn:document.getElementById('reset-btn'),liveMode:document.getElementById('live-mode'),emptyState:document.getElementById('empty-state'),statusBadge:document.getElementById('status-badge'),resultArea:document.getElementById('result-area'),exportSection:document.getElementById('export-section'),exportCopy:document.getElementById('export-copy'),exportTxt:document.getElementById('export-txt'),exportJson:document.getElementById('export-json'),exportPrint:document.getElementById('export-print'),comparisonSection:document.getElementById('comparison-section'),comparisonSelect:document.getElementById('comparison-select'),comparisonTable:document.getElementById('comparison-table'),historySection:document.getElementById('history-section'),historyList:document.getElementById('history-list'),statAlgorithms:document.getElementById('stat-algorithms'),statCharacters:document.getElementById('stat-characters'),statInputSize:document.getElementById('stat-input-size'),statTotal:document.getElementById('stat-total'),statTime:document.getElementById('stat-delta')};
elements.generateBtn.addEventListener('click',generate);elements.resetBtn.addEventListener('click',reset);elements.input.addEventListener('input',function(){if(elements.liveMode.checked)generate();if(elements.input.value.trim()){updateStatus('ready','Ready');}else{updateStatus('','');}});
elements.options.querySelectorAll('input[type="checkbox"]').forEach(function(cb){cb.addEventListener('change',function(){var label=this.parentElement;if(this.checked){label.classList.add('active');}else{label.classList.remove('active');}if(elements.liveMode.checked&&elements.input.value.trim())generate();});});
if(elements.exportCopy)elements.exportCopy.addEventListener('click',exportCopy);if(elements.exportTxt)elements.exportTxt.addEventListener('click',exportTxt);if(elements.exportJson)elements.exportJson.addEventListener('click',exportJson);if(elements.exportPrint)elements.exportPrint.addEventListener('click',exportPrint);if(elements.comparisonSelect)elements.comparisonSelect.addEventListener('change',onComparisonChange);showEmptyState();}

function updateStatus(type,text){if(elements.statusBadge){elements.statusBadge.className='status-badge'+(type?' '+type:'');elements.statusBadge.textContent=text;}}

function showEmptyState(){if(elements.emptyState)elements.emptyState.style.display='flex';if(elements.resultArea)elements.resultArea.style.display='none';}

function showResults(){if(elements.emptyState)elements.emptyState.style.display='none';if(elements.resultArea){elements.resultArea.style.display='block';elements.resultArea.classList.add('show');}}

function generate(){var text=elements.input.value.trim();if(!text){showEmptyState();return;}
updateStatus('processing','Hashing...');
var t0=performance.now();
var algos=[];elements.options.querySelectorAll('input[type="checkbox"]:checked').forEach(function(cb){algos.push(cb.value);});
if(algos.length===0){showToast('Please select at least one algorithm','error');updateStatus('error','Error');return;}
setTimeout(function(){elements.resultsDiv.innerHTML='<div style="text-align:center;padding:var(--space-4);color:var(--color-text-light)">Computing hashes...</div>';showResults();
var promises=algos.map(function(algo){return computeHash(text,algo).then(function(hash){return{algo:algo,hash:hash};});});
Promise.all(promises).then(function(hashes){var t1=performance.now();
elements.resultsDiv.innerHTML='';hashes.forEach(function(item){var row=document.createElement('div');row.className='hg-result-row';
var label=item.algo.toUpperCase();if(label==='SHA1')label='SHA-1';else if(label==='SHA256')label='SHA-256';else if(label==='SHA512')label='SHA-512';else if(label==='MD5')label='MD5';
row.innerHTML='<span class="hg-label">'+label+'</span><span class="hg-value">'+escapeHtml(item.hash)+'</span><button class="hg-copy-btn" data-hash="'+escapeHtml(item.hash)+'">Copy</button>';elements.resultsDiv.appendChild(row);});
elements.resultsDiv.querySelectorAll('.hg-copy-btn').forEach(function(btn){btn.addEventListener('click',function(){if(navigator.clipboard){navigator.clipboard.writeText(btn.dataset.hash).then(function(){btn.textContent='Copied!';setTimeout(function(){btn.textContent='Copy';},1500);});}else{fallbackCopy(btn.dataset.hash);}});});
var chars=text.length;var inputSize=new Blob([text]).size;
var totalHashSize=hashes.reduce(function(s,h){return s+h.hash.length;},0);
var stats={algorithms:algos.length,characters:chars,inputSize:inputSize,totalHashSize:totalHashSize,input:text.substring(0,80)+(text.length>80?'...':''),hashes:hashes,time:t1-t0};
state.results=stats;if(state.history.length>=5)state.history.shift();state.history.push(stats);
elements.statAlgorithms.textContent=algos.length;if(elements.statCharacters)elements.statCharacters.textContent=chars;elements.statInputSize.textContent=formatBytes(inputSize);
elements.statTotal.textContent=hashes.length;if(elements.statTime)elements.statTime.textContent=(t1-t0)<1?'<1 ms':Math.round(t1-t0)+' ms';
var printTitle=document.querySelector('.print-report-title');var printDate=document.querySelector('.print-report-date');if(printTitle)printTitle.textContent='Hash Generator Report';if(printDate)printDate.textContent='Generated on '+new Date().toLocaleString('en-US',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
updateStatus('done','Completed');
if(elements.exportSection)elements.exportSection.style.display='flex';
renderComparison();renderHistory();}).catch(function(err){elements.resultsDiv.innerHTML='<div style="text-align:center;padding:var(--space-4);color:#ef4444;font-size:var(--text-sm)">Error: '+escapeHtml(err.message)+'</div>';updateStatus('error','Error');});},100);}

function computeHash(text,algo){if(algo==='md5'){return Promise.resolve(md5(text));}
if(typeof crypto==='undefined'||!crypto.subtle){return Promise.reject(new Error('Web Crypto API not available. Please use HTTPS.'));}
var name=algo==='sha1'?'SHA-1':algo==='sha256'?'SHA-256':'SHA-512';var encoder=new TextEncoder();var data=encoder.encode(text);
return crypto.subtle.digest(name,data).then(function(buffer){var hashArray=Array.from(new Uint8Array(buffer));return hashArray.map(function(b){return b.toString(16).padStart(2,'0');}).join('');});}

function md5(str){
function safeAdd(x,y){var lsw=(x&0xFFFF)+(y&0xFFFF);var msw=(x>>16)+(y>>16)+(lsw>>16);return(msw<<16)|(lsw&0xFFFF);}
function bitRotateLeft(num,cnt){return(num<<cnt)|(num>>>(32-cnt));}
function md5cmn(q,a,b,x,s,t){return safeAdd(bitRotateLeft(safeAdd(safeAdd(a,q),safeAdd(x,t)),s),b);}
function md5ff(a,b,c,d,x,s,t){return md5cmn((b&c)|(~b&d),a,b,x,s,t);}
function md5gg(a,b,c,d,x,s,t){return md5cmn((b&d)|(c&~d),a,b,x,s,t);}
function md5hh(a,b,c,d,x,s,t){return md5cmn(b^c^d,a,b,x,s,t);}
function md5ii(a,b,c,d,x,s,t){return md5cmn(c^(b|~d),a,b,x,s,t);}
function binlMD5(x,len){x[len>>5]|=0x80<<(len%32);x[((len+64)>>>9<<4)+14]=len;var a=1732584193,b=-271733879,c=-1732584194,d=271733878;for(var i=0;i<x.length;i+=16){var olda=a,oldb=b,oldc=c,oldd=d;
a=md5ff(a,b,c,d,x[i],7,-680876936);d=md5ff(d,a,b,c,x[i+1],12,-389564586);c=md5ff(c,d,a,b,x[i+2],17,606105819);b=md5ff(b,c,d,a,x[i+3],22,-1044525330);
a=md5ff(a,b,c,d,x[i+4],7,-176418897);d=md5ff(d,a,b,c,x[i+5],12,1200080426);c=md5ff(c,d,a,b,x[i+6],17,-1473231341);b=md5ff(b,c,d,a,x[i+7],22,-45705983);
a=md5ff(a,b,c,d,x[i+8],7,1770035416);d=md5ff(d,a,b,c,x[i+9],12,-1958414417);c=md5ff(c,d,a,b,x[i+10],17,-42063);b=md5ff(b,c,d,a,x[i+11],22,-1990404162);
a=md5ff(a,b,c,d,x[i+12],7,1804603682);d=md5ff(d,a,b,c,x[i+13],12,-40341101);c=md5ff(c,d,a,b,x[i+14],17,-1502002290);b=md5ff(b,c,d,a,x[i+15],22,1236535329);
a=md5gg(a,b,c,d,x[i+1],5,-165796510);d=md5gg(d,a,b,c,x[i+6],9,-1069501632);c=md5gg(c,d,a,b,x[i+11],14,643717713);b=md5gg(b,c,d,a,x[i],20,-373897302);
a=md5gg(a,b,c,d,x[i+5],5,-701558691);d=md5gg(d,a,b,c,x[i+10],9,38016083);c=md5gg(c,d,a,b,x[i+15],14,-660478335);b=md5gg(b,c,d,a,x[i+4],20,-405537848);
a=md5gg(a,b,c,d,x[i+9],5,568446438);d=md5gg(d,a,b,c,x[i+14],9,-1019803690);c=md5gg(c,d,a,b,x[i+3],14,-187363961);b=md5gg(b,c,d,a,x[i+8],20,1163531501);
a=md5gg(a,b,c,d,x[i+13],5,-1444681467);d=md5gg(d,a,b,c,x[i+2],9,-51403784);c=md5gg(c,d,a,b,x[i+7],14,1735328473);b=md5gg(b,c,d,a,x[i+12],20,-1926607734);
a=md5hh(a,b,c,d,x[i+5],4,-378558);d=md5hh(d,a,b,c,x[i+8],11,-2022574463);c=md5hh(c,d,a,b,x[i+11],16,1839030562);b=md5hh(b,c,d,a,x[i+14],23,-35309556);
a=md5hh(a,b,c,d,x[i+1],4,-1530992060);d=md5hh(d,a,b,c,x[i+4],11,1272893353);c=md5hh(c,d,a,b,x[i+7],16,-155497632);b=md5hh(b,c,d,a,x[i+10],23,-1094730640);
a=md5hh(a,b,c,d,x[i+13],4,681279174);d=md5hh(d,a,b,c,x[i],11,-358537222);c=md5hh(c,d,a,b,x[i+3],16,-722521979);b=md5hh(b,c,d,a,x[i+6],23,76029189);
a=md5hh(a,b,c,d,x[i+9],4,-640364487);d=md5hh(d,a,b,c,x[i+12],11,-421815835);c=md5hh(c,d,a,b,x[i+15],16,530742520);b=md5hh(b,c,d,a,x[i+2],23,-995338651);
a=md5ii(a,b,c,d,x[i],6,-198630844);d=md5ii(d,a,b,c,x[i+7],10,1126891415);c=md5ii(c,d,a,b,x[i+14],15,-1416354905);b=md5ii(b,c,d,a,x[i+5],21,-57434055);
a=md5ii(a,b,c,d,x[i+12],6,1700485571);d=md5ii(d,a,b,c,x[i+3],10,-1894986606);c=md5ii(c,d,a,b,x[i+10],15,-1051523);b=md5ii(b,c,d,a,x[i+1],21,-2054922799);
a=md5ii(a,b,c,d,x[i+8],6,1873313359);d=md5ii(d,a,b,c,x[i+15],10,-30611744);c=md5ii(c,d,a,b,x[i+6],15,-1560198380);b=md5ii(b,c,d,a,x[i+13],21,1309151649);
a=md5ii(a,b,c,d,x[i+4],6,-145523070);d=md5ii(d,a,b,c,x[i+11],10,-1120210379);c=md5ii(c,d,a,b,x[i+2],15,718787259);b=md5ii(b,c,d,a,x[i+9],21,-343485551);
a=safeAdd(a,olda);b=safeAdd(b,oldb);c=safeAdd(c,oldc);d=safeAdd(d,oldd);}return[a,b,c,d];}
function str2binl(str){var output=[];var mask=(1<<8)-1;for(var i=0;i<str.length*8;i+=8){output[i>>5]|=(str.charCodeAt(i/8)&mask)<<(i%32);}return output;}
function binl2hex(binarray){var hexTab='0123456789abcdef';var str='';for(var i=0;i<binarray.length*4;i++){str+=hexTab.charAt((binarray[i>>2]>>((i%4)*8+4))&0xF)+hexTab.charAt((binarray[i>>2]>>((i%4)*8))&0xF);}return str;}
return binl2hex(binlMD5(str2binl(str),str.length*8));}

function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;
var available=state.history.filter(function(item){return!state.results||item.input!==state.results.input;});
if(available.length===0||state.history.length<=1){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}
if(elements.comparisonSection)elements.comparisonSection.style.display='block';
var html='<option value="">Select previous...</option>';
available.forEach(function(item,i){var idx=state.history.indexOf(item);
html+='<option value="'+idx+'">Hash: '+item.input+' ('+item.algorithms+' algos)</option>';});
elements.comparisonSelect.innerHTML=html;}

function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);
if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}
var prev=state.history[idx];var curr=state.results;
var metrics=[{label:'Algorithms',curr:curr.algorithms,prev:prev.algorithms},{label:'Characters',curr:curr.characters,prev:prev.characters},{label:'Input Bytes',curr:formatBytes(curr.inputSize),prev:formatBytes(prev.inputSize)},{label:'Hashes',curr:curr.total,prev:prev.total}];
var html='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';
metrics.forEach(function(m){var diff=typeof m.curr==='number'?m.curr-m.prev:0;
var arrow=diff>0?'<span class="comp-up">+'+diff+'</span>':diff<0?'<span class="comp-down">'+diff+'</span>':'<span class="comp-same">0</span>';
html+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});
html+='</tbody></table>';elements.comparisonTable.innerHTML=html;}

function renderHistory(){if(!elements.historyList)return;
if(state.history.length<=1){if(elements.historySection)elements.historySection.style.display='none';return;}
if(elements.historySection)elements.historySection.style.display='block';
var html='';for(var i=state.history.length-1;i>=0;i--){var item=state.history[i];
var active=state.results&&item.input===state.results.input?' style="border-color:var(--color-primary);background:rgba(37,99,235,0.05)"':'';
html+='<div class="history-item"'+active+'><div class="history-meta"><span class="history-time">Hashed</span><span class="history-size">'+item.characters+' chars, '+formatBytes(item.inputSize)+'</span></div><div class="history-lines">'+item.algorithms+' algos, '+item.total+' hashes</div></div>';}
elements.historyList.innerHTML=html;}

function exportCopy(){if(!state.results)return;var r=state.results;var text='Hash Generator Report\n====================\n\nEncoding: UTF-8\nCharacters: '+r.characters+'\nInput Bytes: '+formatBytes(r.inputSize)+'\nAlgorithms: '+r.algorithms+'\nTotal Hashes: '+r.total+'\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\n';r.hashes.forEach(function(h){text+=h.algo.toUpperCase()+': '+h.hash+'\n';});
if(navigator.clipboard){navigator.clipboard.writeText(text.trim()).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(text.trim());}}

function exportTxt(){if(!state.results)return;var r=state.results;var text='Hash Generator Report\n====================\n\nEncoding: UTF-8\nCharacters: '+r.characters+'\nInput Bytes: '+formatBytes(r.inputSize)+'\nAlgorithms: '+r.algorithms+'\nTotal Hashes: '+r.total+'\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\n';r.hashes.forEach(function(h){text+=h.algo.toUpperCase()+': '+h.hash+'\n';});downloadFile('hash-report.txt',text,'text/plain');showToast('Downloaded TXT report','success');}

function exportJson(){if(!state.results)return;var obj={encoding:'UTF-8',characters:state.results.characters,inputSize:state.results.inputSize,algorithms:state.results.algorithms,hashes:{},processingTimeMs:Math.round(state.results.time),timestamp:new Date().toISOString()};state.results.hashes.forEach(function(h){obj.hashes[h.algo]=h.hash;});var json=JSON.stringify(obj,null,2);downloadFile('hash-report.json',json,'application/json');showToast('Downloaded JSON report','success');}

function exportPrint(){window.print();}
function downloadFile(filename,content,mimeType){var blob=new Blob([content],{type:mimeType});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}
function reset(){elements.input.value='';elements.resultsDiv.innerHTML='';state.results=null;state.history=[];if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.historySection)elements.historySection.style.display='none';if(elements.comparisonSection)elements.comparisonSection.style.display='none';}
function formatBytes(bytes){if(!bytes)return'0 B';if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function escapeHtml(str){if(typeof str!=='string')return'';return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();
